PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://example.org/reference#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?class ?tsid ?label WHERE {
  ?z brick:hasIdentifier "Zone_F3_Z01" .
  ?z rdfs:label ?zlabel .
  ?point brick:isPointOf ?z .
  ?point a ?class .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
  OPTIONAL { ?point rdfs:label ?label . }
}

